// Default std::priority_queue is a MAX heap
#include <queue>
#include <vector>
#include <iostream>
using namespace std;

int main() {
    priority_queue<int> maxHeap;

    maxHeap.push(5);
    maxHeap.push(1);
    maxHeap.push(9);
    maxHeap.push(3);

    cout << maxHeap.top() << endl; // prints 9, the largest
    maxHeap.pop();                 // removes 9
    cout << maxHeap.top() << endl; // prints 5
    return 0;
}

// MIN heap: smallest element is always at top()
priority_queue<int, vector<int>, greater<int>> minHeap;

minHeap.push(5);
minHeap.push(1);
minHeap.push(9);
minHeap.push(3);

