#include <queue>
#include <vector>
using namespace std;

vector<int> kLargest(vector<int>& nums, int k) {
    priority_queue<int, vector<int>, greater<int>> minHeap;

    for (int num : nums) {
        minHeap.push(num);
        if ((int)minHeap.size() > k) {
            minHeap.pop(); // discard current smallest of the top k
        }
    }

    // Heap now holds exactly the k largest elements
    vector<int> result;
    while (!minHeap.empty()) {
        result.push_back(minHeap.top());
        minHeap.pop();
    }
    return result; // comes out in ascending order, since we drained a min heap
}

